// Delivery audio is accepted only after its bytes match the server's receipt.
export async function checkedDeliveryAudio(result) {
 if (typeof result?.audioBase64 !== 'string' || result.audioBase64.length > 8 * 1024 * 1024 || !/^[0-9a-f]{64}$/.test(result.audioSha256 || '')) throw Error('Audio unavailable');
 const raw=atob(result.audioBase64), bytes=Uint8Array.from(raw, c=>c.charCodeAt(0));
 if (bytes.length < 44 || bytes.length > 6 * 1024 * 1024 || String.fromCharCode(...bytes.subarray(0,4)) !== 'RIFF' || String.fromCharCode(...bytes.subarray(8,12)) !== 'WAVE') throw Error('Unsupported audio');
 const digest=await crypto.subtle.digest('SHA-256',bytes);
 if ([...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('') !== result.audioSha256) throw Error('Audio receipt mismatch');
 return bytes.buffer;
}

